void VBlank(void)
{
    InVBlank = 1;
    ReadPaddHardware();
    cdtime--;
    DualShockStuff();
    if (VBlankSpecific)
        VBlankSpecific();
    if (UsePollHost)
        pollhost();
    VBFrameCount += PalNtscRate;
    if (!Paused) {
        if (LevelIsMultiPlayer)
            VBLevelTicks += 5;
        else
            VBLevelTicks += PalNtscRate;
    }
    InVBlank = 0;
}

void DrawSyncInt(void)
{
    if (GpuTimerEnable)
        DrawStopTime = GetRCnt(0xf2000001);
}

void DoubleTrebleBuffer(void)
{
    int Temp;

    Temp = TbFrame[0];
    TbFrame[0] = TbFrame[1];
    TbFrame[1] = TbFrame[2];
    TbFrame[2] = Temp;
    DbFrame[1] = DbFrame[0];
    DbFrame[0] = 1 - DbFrame[0];
    currdb = &db[DbFrame[0]];
    olddb = &db[DbFrame[1]];
}

/* The function-local static ScrShot is unnamed (D_800AE890) in the original; initialised, so in
   .sdata after aab. */
int MainGameLoop(void)
{
    static int ScrShot = 0;

    LevelComplete = 0;
    quitgame = 0;
    if (GameRunningMode == 1 && !aab) {
        aab = 1;
        LevelComplete = 10;
    }
    DbFrame[0] = 0;
    DbFrame[1] = 1;
    TbFrame[0] = 0;
    TbFrame[1] = 1;
    TbFrame[2] = 2;
    levelfade = 255;
    levelfadespeed = -16;
    LastNewVcounts = 0;
    NewVcounts = 0;
    while (!LevelComplete) {
        CdCheckMusic();
        NewPadRead();
        DoubleTrebleBuffer();
        ClearOTag(currdb->InitOt, 217);
        LevelTicks = VBLevelTicks;
        FrameCount = VBFrameCount;
        RealVCounts = VBFrameCount;
        if (!GameIsPaused()) {
            if (JustLoaded) {
                JustLoaded = 0;
                NewVcounts = PalNtscRate * 2;
                LevelTicks = OldLevelTicks = VBLevelTicks + NewVcounts;
                targetcdvol = GetsMusic() * 2;
            } else {
                LastNewVcounts = NewVcounts;
                if (!FrameCompOn)
                    NewVcounts = PalNtscRate * 2;
                else
                    NewVcounts = FrameCount;
            }
        } else {
            LastNewVcounts = NewVcounts;
            NewVcounts = 0;
        }
        if (NewVcounts > 30)
            NewVcounts = 30;
        VBFrameCount = 0;
        FrameCount = 0;
        SwapAllButtons();
        if (MainLoop)
            MainLoop();
        ProcessorStopTime = GetRCnt(0xf2000001);
        DrawSync(0);
        VSync(2);
        if (ScreenShotOn && (GameWindows[0].Input.Original & 8)) {
            if (!ScrShot) {
                SaveBMP();
                ScrShot = 1;
            }
        } else {
            ScrShot = 0;
        }
        if (TimebarOn)
            DrawTimeBar();
        ProcessorStartTime = GetRCnt(0xf2000001);
        PutDispEnv(&currdb->DispEnv);
        DrawOTag(currdb->InitOt);
        DrawStartTime = GetRCnt(0xf2000001);
        GpuTimerEnable = 1;
        if (EndSpecific)
            EndSpecific();
    }
    VBLevelTicks = 0;
    VBFrameCount = 0;
    if (LevelComplete == 7)
        GameInterMission();
    if (LevelComplete == 12)
        DoIntro = 1;
    if (LevelComplete == 13)
        DoExtro = 1;
    if (LevelComplete == 15)
        DoLogos2 = 1;
    else if (LevelComplete == 14)
        DoLogos = 1;
    if (LevelComplete == 5)
        GameNewGame();
    if (LevelComplete == 8)
        GameDemoExit();
    if (LevelComplete == 10)
        GameSelfPlay();
    if (LevelComplete == 1 && GameRunningMode == 2)
        GameMagDemoLevel();
    if (LevelComplete == 11)
        GameMPlayerExit();
    if (LevelComplete == 19)
        GameReRunMPLevel();
    if (LevelComplete == 20)
        RestartLevel(1);
    if (LevelComplete == 21)
        RestartLevel(0);
    if (LevelComplete == 16)
        GameQuitGame();
    if (LevelComplete == 6)
        SetFrontEndStartScreen(0);
    if (LevelComplete == 18) {
        SetFrontEndStartScreen(2);
        LevelComplete = 6;
    }
    if (LevelComplete == 17) {
        SetFrontEndStartScreen(1);
        LevelComplete = 6;
    }
    GpuTimerEnable = 0;
    errordetectflag = 0;
    killallsounds();
    freeallmallocs();
    if (UseCdData) {
        while (!CdControlB(8, 0, 0))
            ;
    }
    return LevelComplete;
}

int MainInterMissionLoop(void)
{
    char EndInterMission;

    CdCheckMusic();
    NewPadRead();
    DoubleTrebleBuffer();
    ClearOTag(currdb->InitOt, 217);
    LevelTicks = VBLevelTicks;
    FrameCount = VBFrameCount;
    RealVCounts = VBFrameCount;
    LastNewVcounts = NewVcounts;
    if (!FrameCompOn)
        NewVcounts = PalNtscRate * 2;
    else
        NewVcounts = VBFrameCount;
    if (NewVcounts > 30)
        NewVcounts = 30;
    VBFrameCount = 0;
    FrameCount = 0;
    SwapAllButtons();
    EndInterMission = PadEndInterMission();
    DBInterMission();
    QuakeInterMissionLoop();
    ProcessorStopTime = GetRCnt(0xf2000001);
    DrawSync(0);
    VSync(2);
    if (TimebarOn)
        DrawTimeBar();
    ProcessorStartTime = GetRCnt(0xf2000001);
    PutDispEnv(&currdb->DispEnv);
    DrawOTag(currdb->InitOt);
    DrawStartTime = GetRCnt(0xf2000001);
    GpuTimerEnable = 1;
    if (EndSpecific)
        EndSpecific();
    return EndInterMission;
}

void GameInterMission(void)
{
    SetInterMission();
    KillModel(&Creatures[0]);
    KillModel(&Creatures[1]);
    PrintLevelInterMission();
    while (!MainInterMissionLoop())
        ;
    if (Mission == 5) {
        NextLevelName = IDNAME("Extro FMV");
        LevelComplete = 13;
    } else {
        NextLevelName = IDNAME("EndMission 0");
        MainStartName = IDNAME("Default");
        LevelComplete = 2;
        NextLevelName.Name[11] += Mission;
    }
    ClearLevelIntermission();
}

void ProcessGame(void)
{
    SetFrontEndStartScreen(0);
    while (1) {
        DeleteAllMatchingMemory(3);
        ClearLots();
        if (GameRunningMode) {
            DoIntro = 0;
            DoExtro = 0;
        }
        if (DoLogos2 && GameRunningMode != 1) {
            GameLogos2();
            DoLogos2 = 0;
        } else if (DoLogos && GameRunningMode != 1) {
            GameLogos();
            DoLogos = 0;
        } else if (DoIntro) {
            GameIntro();
            DoIntro = 0;
        } else if (DoExtro) {
            GameExtro();
            DoExtro = 0;
        } else {
            DoLogos = 0;
            DoLogos2 = 0;
            GameTitle();
        }
        LastLevelComplete = 5;
        LevelComplete = 0;
        while (!DoLogos && !DoLogos2 && !DoIntro && !DoExtro) {
            GameNewMission();
            srand(13);
            LevelChange++;
            GetLevelData(NextLevelName);
            LastLevelComplete = LevelComplete;
            TestIt("Hassle.Psx");
            LoadLevel();
            VBlankSpecific = 0;
            TitleLoad = 0;
            if (MainGameLoop() == 9)
                return;
            if (LevelComplete == 6)
                break;
        }
    }
}

void ProcessGame(void);

int main(void)
{
    int a;
    int *heap;

    GameTimeOutTime = 0;
    GameNoInputTime = 0;
    GameTimeOutTime = 0;
    GameTime = 0;
    a = -(_stacksize + 0x80000000) + _ramsize;
    a -= __bss;
    EnterCriticalSection();
    heap = (int *)__bss;
    while (a > 0) {
        heap[0] = 0;
        heap[1] = 0;
        heap += 2;
        a -= 8;
    }
    ExitCriticalSection();
    DummyMemory = (long *)primlistarray;
    screen256pal = (short *)primlistarray;
    DoLogos2 = 1;
    TitleLoad = 1;
    FrameCompOn = 1;
    DoLogos = 0;
    DoIntro = 0;
    DoExtro = 0;
    PalNtsc = 5;
    QuakeFillInLevelEngineSideInterface();
    FrontEndResetVideoDefaults();
    Config_InstallVideo();
    FrameCount = 0;
    PalNtscRate = PalNtsc;
    InitialiseAfterReset();
    StoreGP_();
    initMYmalloc2();
    ResetCallback();
    SetDispMask(0);
    MemCardInit(0);
    MemCardStart();
    PadInitMtap(&padbuffer1, &padbuffer2);
    PadStartCom();
    ResetGraph(0);
    SetGraphDebug(0);
    SfxInit(2);
    MYPCinit();
    GpuTimerEnable = 0;
    InitialiseDrawNewGame();
    InitSoundNewGame();
    VSyncCallback(VBlank);
    DrawSyncCallback(DrawSyncInt);
    dprintf(0, "Begin Game");
    ProcessGame();
    return 0;
}
